    vxd, vyd = state["vx"], state["vy"]
    x, y = pd[0], pd[1]
    front, up, down = sandbox.get_whisker_readings()

    # Maintain height to reduce floor friction
    fy = 20.0 * (TARGET_Y - y) - 20.0 * vyd

    # Whisker-based navigation to avoid obstacles
    lateral_force = 0.0
    # Use front whisker for early obstacle detection
    if front < WALL_AVOIDANCE_THRESHOLD:
        # Apply rightward force to avoid left wall
        lateral_force = -30.0 * (WALL_AVOIDANCE_THRESHOLD - front)
    # Avoid floor contact (down whisker < 0.3 m)
    if down < 0.3:
        lateral_force += 10.0  # Slight upward force
    # Avoid ceiling contact (up whisker < 0.3 m)
    if up < 0.3:
        lateral_force -= 10.0  # Slight downward force

