        # Dynamic forward force with velocity-based scaling
        # fx = base_force + velocity_compensation to overcome damping
        if x < 5.0:
            fx = 500.0 + 20.0 * vxd  # Strong forward force with velocity-based scaling
        else:
            # Reduce force as approaching activation zone
            fx = 250.0 + 10.0 * vxd
